/**
 * Encryption-at-rest for the session secrets (the "pickle key" pattern):
 * a random AES-GCM key is generated by WebCrypto as NON-EXTRACTABLE and kept in
 * IndexedDB as a CryptoKey object. JavaScript (including any injected script)
 * can ask the browser to use it but can never read the raw key bytes, so a copy
 * of the browser's storage files alone does not reveal the access token.
 *
 * No cryptography is implemented here: this only calls WebCrypto.
 */

export interface SealedSecret {
  v: 1;
  iv: Uint8Array<ArrayBuffer>;
  ct: ArrayBuffer;
}

const enc = new TextEncoder();
const dec = new TextDecoder();

export function generatePickleKey(): Promise<CryptoKey> {
  return crypto.subtle.generateKey({ name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
}

/** Encrypts `plaintext`; `context` is bound as additional authenticated data. */
export async function seal(key: CryptoKey, plaintext: string, context: string): Promise<SealedSecret> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = await crypto.subtle.encrypt({ name: "AES-GCM", iv, additionalData: enc.encode(context) }, key, enc.encode(plaintext));
  return { v: 1, iv, ct };
}

export async function unseal(key: CryptoKey, sealed: SealedSecret, context: string): Promise<string> {
  if (!sealed || sealed.v !== 1) throw new Error("Unsupported sealed secret format");
  const pt = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: sealed.iv, additionalData: enc.encode(context) },
    key,
    sealed.ct,
  );
  return dec.decode(pt);
}

/** Random secret (base64url, no padding) from the browser CSPRNG. */
export function randomSecret(bytes = 32): string {
  const b = crypto.getRandomValues(new Uint8Array(bytes));
  let s = "";
  for (const x of b) s += String.fromCharCode(x);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
